#pragma once

#include "curvy/settings.h"
#include "curvy/workspacecontroller.h"

#include <newui/application.h>
#include <newui/bundle.h>
#include <newui/frame.h>
#include <newui/rootview.h>

#include <gtest/gtest.h>

#include <filesystem>
#include <memory>
#include <string>

// Both generated by reflectgen (see main.cpp): newui's classes first, then curvy's.
extern void registerReflectionData();
extern void registerCurvyReflection();

namespace curvytest {

    inline void registerReflection() {
        static const bool done = [] {
            registerReflectionData();
            registerCurvyReflection();
            return true;
        }();
        (void)done;
    }

    inline std::filesystem::path tempFile(const char* name) {
        return std::filesystem::temp_directory_path() / name;
    }

    // The workspace as the app builds it from Resources/workspace.newui, with default settings that are never written to disk, in a real
    // window (created hidden, as the controller builds its views and the tool window when the window exists): the tests drive the controller
    // and the views directly.
    class WorkspaceTest : public ::testing::Test {
    protected:
        void SetUp() override {
            registerReflection();
            curvy::WorkspaceController::applyTheme(true);
            newui::Application& app = newui::Application::instance();
            app.setName("curvy");
            app.setFrame(&frame_);
            frame_.setName("workspace");
            ASSERT_TRUE(newui::Bundle::instance().loadFrame(frame_));
            window_ = std::make_unique<curvy::WorkspaceController>(frame_, settings_, std::string());
            ASSERT_TRUE(frame_.initialize());
            ::ShowWindow(frame_.frameHandle(), SW_HIDE);   // Frame::initialize shows it; the controller loaded during creation
            ASSERT_TRUE(window_->isLoaded());
            ASSERT_EQ(window_->loadError(), "");
            frame_.rootView().updateLayout();
        }

        void TearDown() override {
            window_.reset();
            if (frame_.frameHandle() != nullptr) {
                ::DestroyWindow(frame_.frameHandle());
            }
            MSG quit;
            while (::PeekMessage(&quit, nullptr, WM_QUIT, WM_QUIT, PM_REMOVE)) {   // destroying the main Frame posts WM_QUIT; later tests must not see it
            }
            newui::Application::instance().setFrame(nullptr);
        }

        curvy::WorkspaceController& window() { return *window_; }

        newui::Frame frame_;
        curvy::Settings settings_;
        std::unique_ptr<curvy::WorkspaceController> window_;
    };

}
